-- Not SARGable: function on the column forces a scan
SELECT OrderId, Total FROM dbo.Orders
WHERE YEAR(OrderDate) = 2024 AND CustomerId = @cid;

-- SARGable range on the bare column
SELECT OrderId, Total FROM dbo.Orders
WHERE OrderDate >= '20240101' AND OrderDate < '20250101'
  AND CustomerId = @cid;

-- Covering index: seek on keys, Total carried in the leaf
CREATE NONCLUSTERED INDEX IX_Orders_Customer_Date
  ON dbo.Orders (CustomerId, OrderDate)
  INCLUDE (Total);

-- After a big load
UPDATE STATISTICS dbo.Orders WITH FULLSCAN;

CREATE EXTENSION IF NOT EXISTS vector;

CREATE TABLE chunks (
  id        bigserial PRIMARY KEY,
  matter_id text NOT NULL,
  body      text NOT NULL,
  meta      jsonb,
  embedding vector(1024)
);
CREATE INDEX ON chunks USING hnsw (embedding vector_cosine_ops);
CREATE INDEX ON chunks USING gin (meta);

-- top 5 chunks for one matter, cosine distance
SELECT id, body
FROM chunks
WHERE matter_id = 'M-42'
ORDER BY embedding <=> $1
LIMIT 5;

// Embed: bounded, read together
{ _id: ObjectId("..."), orderNo: "T-2025-118", status: "open",
  lines: [ { sku: "A1", qty: 2, price: NumberDecimal("19.90") } ] }

// Reference: unbounded, own lifecycle
{ _id: ObjectId("..."), orderId: ObjectId("..."), at: ISODate("..."), event: "approved" }

// ESR: equality (status), sort (createdAt), range (total)
db.orders.createIndex({ status: 1, createdAt: -1, total: 1 })

db.orders.aggregate([
  { $match: { status: "open" } },
  { $unwind: "$lines" },
  { $group: { _id: "$lines.sku", qty: { $sum: "$lines.qty" } } },
  { $sort: { qty: -1 } }, { $limit: 10 }
])
